mapper.select:
SELECT id, user_id,real_name, id_type, id_card,
       discount_type, phone, verify_status,
       create_time, update_time
FROM passenger

    AND user_id = #{userId}
    AND real_name LIKE CONCAT('%', #{realName}, '%')
    AND verify_status = #{verifyStatus}
    AND discount_type = #{discountType}


    ORDER BY ${sortField}


            ASC
            DESC
            ASC 


    ASC

